int rankCCCs[12] = { 0, 0, 55, 65, 75, 85, 95, 105, 115, 125, 135, 145 };
int rankNMLs[12] = { 0, 0, 0, 0, 0, 0, 0, 400, 500, 600, 700, 1200 };
