Tprofile_load *load_profile(char *handle)
{
    char file[1024];
    void *fp;
    Tprofile_load *p;
    int cs;

    get_profile_dir_for_profile(file, 1024, handle);
    sprintf(file, "%s%s.itp", file, handle);
    fp = fopen(file, "rb");
    if (!fp)
        return 0;
    p = malloc(0x550);
    fread(p, 0x550, 1, fp);
    load_control(get_controls(), fp);
    fclose(fp);
    cs = generate_profile_checksum(p);
    if (cs != p->checksum) {
        free(p);
        p = 0;
    }
    return p;
}

