    get_profile_dir_for_profile(file, 1024, handle);
    sprintf(file, "%s%s.itp", file, handle);
    delete_file(file);
    get_profile_dir_for_profile(file, 1024, handle);
    sprintf(file, "%s%s_stats.txt", file, handle);
    delete_file(file);
    get_profile_dir_for_profile(file, 1024, handle);
    rmdir(file);
}

